/**
 * @method
 * @name bitstamp#fetchMarkets
 * @description retrieves data on all markets for bitstamp
 * @see https://www.bitstamp.net/api/#tag/Market-info/operation/GetTradingPairsInfo
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Bitstamp) FetchMarketsAsync(optionalArgs ...any) <-chan AsyncResult[[]MarketInterface] {
	ch := make(chan AsyncResult[[]MarketInterface], 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.FetchMarketsFromCacheAsync(params)
	if r.Err != nil {
		panic(r.Err)
	}
	listRecv1157, _ := MapSliceToList(r.Value), r.Value != nil
	var response []any = listRecv1157
	//
	//    [
	//
	//   spot:
	//
	//        {
	//            "name": "BTC/USD",
	//            "market_symbol": "btcusd",
	//            "base_currency": "BTC",
	//            "base_decimals": 8,
	//            "counter_currency": "USD",
	//            "counter_decimals": 0,
	//            "minimum_order_value": "10",
	//            "trading": "Enabled",
	//            "instant_order_counter_decimals": 2,
	//            "instant_and_market_orders": "Enabled",
	//            "description": "Bitcoin / U.S. dollar",
	//            "market_type": "SPOT"
	//        },
	//        ...
	//
	//    perp:
	//
	//         {
	//             "name": "BTC/USD-PERP",
	//             "market_symbol": "btcusd-perp",
	//             "base_currency": "BTC",
	//             "base_decimals": 5,
	//             "counter_currency": "USD",
	//             "counter_decimals": 0,
	//             "minimum_order_value": "10",
	//             "maximum_order_value": "500000.00000000",
	//             "minimum_order_amount": "0.00001000",
	//             "maximum_order_amount": "10.00000000",
	//             "trading": "Enabled",
	//             "instant_order_counter_decimals": 2,
	//             "instant_and_market_orders": "Enabled",
	//             "description": "Bitcoin / U.S. dollar Perpetual",
	//             "market_type": "PERPETUAL",
	//             "underlying_asset": "Kaiko BTC Benchmark Reference Rate",
	//             "payoff_type": "Linear",
	//             "contract_size": "1.00000000",
	//             "isin": "EZHKD4DNKHY3"
	//         }
	//
	var result []any = []any{}
	for i := 0; i < len(response); i++ {
		var market map[string]any = SafeMapTyped(response, i)
		var baseId *string = this.SafeString(market, "base_currency")
		var quoteId *string = this.SafeString(market, "counter_currency")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var settleId *string = nil
		var marketTypeRaw *string = this.SafeString(market, "market_type")
		var symbol string = *base + "/" + *quote
		var typeVar *string = nil
		var subType *string = nil
		if marketTypeRaw != nil && *marketTypeRaw == "SPOT" {
			typeVar = SafeStringPtr("spot")
		} else if marketTypeRaw != nil && *marketTypeRaw == "PERPETUAL" {
			typeVar = SafeStringPtr("swap")
			settleId = quoteId
			symbol = *base + "/" + *quote + ":" + *this.SafeString(market, "counter_currency", "")
			var payoffType *string = this.SafeString(market, "payoff_type")
			if payoffType != nil && *payoffType == "Linear" {
				subType = SafeStringPtr("linear")
			} else if payoffType != nil && *payoffType == "Inverse" {
				subType = SafeStringPtr("inverse")
			}
		}
		var isSpot bool = (typeVar != nil && *typeVar == "spot")
		var settle *string = func() *string {
			if (settleId != nil) && (settleId == nil || *settleId != "") {
				return this.SafeCurrencyCode(settleId)
			}
			return nil
		}()
		result = append(result, map[string]any{
			"id":       this.SafeString(market, "market_symbol"),
			"symbol":   symbol,
			"base":     base,
			"quote":    quote,
			"settle":   settle,
			"baseId":   baseId,
			"quoteId":  quoteId,
			"settleId": settleId,
			"type":     typeVar,
			"subType":  subType,
			"spot":     isSpot,
			"margin":   false,
			"future":   false,
			"swap":     !isSpot,
			"option":   false,
			"active":   (this.SafeString(market, "trading") != nil && *this.SafeString(market, "trading") == "Enabled"),
			"contract": !isSpot,
			"linear": func() any {
				if isSpot {
					return nil
				}
				return true
			}(),
			"inverse": func() any {
				if isSpot {
					return nil
				}
				return false
			}(),
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "base_decimals"))),
				"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "counter_decimals"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(market, "minimum_order_amount"),
					"max": this.SafeNumber(market, "maximum_order_amount"),
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": this.SafeNumber(market, "minimum_order_value"),
					"max": this.SafeNumber(market, "maximum_order_value"),
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}
func (this *Bitstamp) ConstructCurrencyObject(id *string, code string, name *string, precision *int64, minCost any, originalPayload map[string]any) map[string]any {
	var currencyType string = "crypto"
	var description map[string]any = this.Describe()
	var fees map[string]any = SafeMapTyped(description, "fees")
	var fundingFees map[string]any = SafeMapTyped(fees, "funding")
	var withdrawFee *float64 = this.SafeNumber(fundingFees, "withdraw")
	if this.IsFiat(code) {
		currencyType = "fiat"
	}
	var tickSize *float64 = this.ParseNumber(this.ParsePrecision(this.NumberToString(precision)))
	return map[string]any{
		"id":        id,
		"code":      code,
		"info":      originalPayload,
		"type":      currencyType,
		"name":      name,
		"active":    true,
		"deposit":   nil,
		"withdraw":  nil,
		"fee":       withdrawFee,
		"precision": tickSize,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": tickSize,
				"max": nil,
			},
			"price": map[string]any{
				"min": tickSize,
				"max": nil,
			},
			"cost": map[string]any{
				"min": minCost,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": map[string]any{},
	}
}
func (this *Bitstamp) FetchMarketsFromCacheAsync(optionalArgs ...any) <-chan AsyncResult[[]map[string]any] {
	ch := make(chan AsyncResult[[]map[string]any], 1)
	go this.fetchMarketsFromCacheBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchMarketsFromCacheBody(ch chan AsyncResult[[]map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// this method is now redundant
	// currencies are now fetched before markets
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var options map[string]any = this.SafeDictMap(this.Options, "fetchMarkets", map[string]any{})
	var timestamp *int64 = this.SafeInteger(options, "timestamp")
	var expires int64 = *this.SafeInteger(options, "expires", 1000)
	var now int64 = this.Milliseconds()
	if (timestamp == nil) || ((now - *timestamp) > expires) {

		r := <-this.PublicGetMarkets(params)
		if r.Err != nil {
			panic(r.Err)
		}
		response := r.Raw
		//
		//    [
		//        {
		//            "name": "BTC/USD",
		//            "market_symbol": "btcusd",
		//            "base_currency": "BTC",
		//            "base_decimals": 8,
		//            "counter_currency": "USD",
		//            "counter_decimals": 0,
		//            "minimum_order_value": "10",
		//            "trading": "Enabled",
		//            "instant_order_counter_decimals": 2,
		//            "instant_and_market_orders": "Enabled",
		//            "description": "Bitcoin / U.S. dollar",
		//            "market_type": "SPOT"
		//        },
		//
		this.Options["fetchMarkets"] = this.Extend(options, map[string]any{
			"response":  response,
			"timestamp": now,
		})
	}
	var cache map[string]any = SafeMapTyped(this.Options, "fetchMarkets")
	var markets []any = SafeListTypedDefault(cache, "response", []any{})

	ch <- AsyncResult[[]map[string]any]{Value: MapSliceFromList(markets)}
	return nil
}

/**
 * @method
 * @name bitstamp#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://www.bitstamp.net/api/#tag/Market-info/operation/GetTradingPairsInfo
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Bitstamp) FetchCurrenciesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.FetchMarketsFromCacheAsync(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response any = nil
	if r.Value != nil {
		response = MapSliceToList(r.Value)
	}

	//
	//     [
	//         {
	//             "trading": "Enabled",
	//             "base_decimals": 8,
	//             "url_symbol": "btcusd",
	//             "name": "BTC/USD",
	//             "instant_and_market_orders": "Enabled",
	//             "minimum_order": "20.0 USD",
	//             "counter_decimals": 2,
	//             "description": "Bitcoin / U.S. dollar"
	//         },
	//     ]
	//
	ch <- AsyncResult[map[string]any]{Value: this.ParseCurrencies(response)}
	return nil
}
func (this *Bitstamp) ParseCurrencies(rawCurrencies any) map[string]any {
	// each market row yields two currencies so the accumulation happens
	// in a local dictionary here instead of a temp key inside this.options
	// because the shared scratch key raced between concurrent
	// fetchCurrencies invocations in the multi threaded runtimes
	var result map[string]any = map[string]any{}
	var arr []any = this.ToArray(rawCurrencies)
	for i := 0; i < len(arr); i++ {
		var market map[string]any = this.SafeDictMap(arr, i, map[string]any{})
		var baseId *string = this.SafeString(market, "base_currency")
		var quoteId *string = this.SafeString(market, "counter_currency")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		var description *string = this.SafeString(market, "description")
		if description == nil {
			panic(ExchangeError(this.Id + " parseCurrencies() missing description"))
		}
		var descriptionParts []string = strings.Split(*description, " / ")
		var baseDescription *string = this.SafeString(descriptionParts, 0)
		var quoteDescription *string = this.SafeString(descriptionParts, 1)
		var minimumOrder *string = this.SafeString(market, "minimum_order_value")
		if minimumOrder == nil {
			panic(ExchangeError(this.Id + " parseCurrencies() missing minimumOrder"))
		}
		var parts []string = strings.Split(*minimumOrder, " ")
		var cost *string = this.SafeString(parts, 0)
		if base != nil {
			if _, ok := result[*base]; !ok {
				var baseDecimals *int64 = this.SafeInteger(market, "base_decimals")
				result[*base] = this.ConstructCurrencyObject(baseId, *base, baseDescription, baseDecimals, nil, market)
			}
		}
		if quote != nil {
			if _, ok := result[*quote]; !ok {
				var counterDecimals *int64 = this.SafeInteger(market, "counter_decimals")
				result[*quote] = this.ConstructCurrencyObject(quoteId, *quote, quoteDescription, counterDecimals, this.ParseNumber(cost), market)
			}
		}
	}
	return result
}

/**
 * @method
 * @name bitstamp#fetchOrderBook
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://www.bitstamp.net/api/#tag/Order-book/operation/GetOrderBook
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Bitstamp) FetchOrderBookAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[OrderBook] {
	ch := make(chan AsyncResult[OrderBook], 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchOrderBookBody(ch chan AsyncResult[OrderBook], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": market["id"],
	}

	r1 := <-this.PublicGetOrderBookPair(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "timestamp": "1583652948",
	//         "microtimestamp": "1583652948955826",
	//         "bids": [
	//             [ "8750.00", "1.33685271" ],
	//             [ "8749.39", "0.07700000" ],
	//             [ "8746.98", "0.07400000" ],
	//         ]
	//         "asks": [
	//             [ "8754.10", "1.51995636" ],
	//             [ "8754.71", "1.40000000" ],
	//             [ "8754.72", "2.50000000" ],
	//         ]
	//     }
	//
	var microtimestamp *int64 = this.SafeInteger(response, "microtimestamp")
	if microtimestamp == nil {
		panic(ExchangeError(this.Id + " fetchOrderBook() missing microtimestamp"))
	}
	var timestamp int64 = this.ParseToInt(float64(*microtimestamp) / 1000)
	var orderbook map[string]any = this.ParseOrderBook(response, market["symbol"], timestamp)
	orderbook["nonce"] = microtimestamp

	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(orderbook)}
	return nil
}
func (this *Bitstamp) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	// {
	//     "timestamp": "1686068944",
	//     "high": "26252",
	//     "last": "26216",
	//     "bid": "26208",
	//     "vwap": "25681",
	//     "volume": "3563.13819902",
	//     "low": "25350",
	//     "ask": "26211",
	//     "open": "25730",
	//     "open_24": "25895",
	//     "percent_change_24": "1.24",
	//     "pair": "BTC/USD"
	// }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "pair")
	var symbol *string = this.SafeSymbol(marketId, market)
	var timestamp *int64 = this.SafeTimestamp(ticker, "timestamp")
	var vwap *string = this.SafeString(ticker, "vwap")
	var baseVolume *string = this.SafeString(ticker, "volume")
	var quoteVolume *string = Precise.StringMul(baseVolume, vwap)
	var last *string = this.SafeString(ticker, "last")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          vwap,
		"open":          this.SafeString(ticker, "open"),
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   quoteVolume,
		"info":          ticker,
	}, market)
}

