/**
 * @method
 * @name bitstamp#createOrder
 * @description create a trade order
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenInstantBuyOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenMarketBuyOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenLimitBuyOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenInstantSellOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenMarketSellOrder
 * @see https://www.bitstamp.net/api/#tag/Orders/operation/OpenLimitSellOrder
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bitstamp) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Bitstamp) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair":   market["id"],
		"amount": this.AmountToPrecision(symbol, amount),
	}
	var clientOrderId *string = this.SafeString2(params, "client_order_id", "clientOrderId")
	if clientOrderId != nil {
		request["client_order_id"] = clientOrderId
	}
	var paramsOmitted map[string]any = func() map[string]any {
		if clientOrderId != nil {
			return this.OmitDict(params, []any{"clientOrderId"})
		}
		return params
	}()
	var response map[string]any = nil
	var capitalizedSide string = this.Capitalize(side)
	if typeVar == "market" {
		if capitalizedSide == "Buy" {

			r1 := <-this.PrivatePostBuyMarketPair(this.Extend(request, paramsOmitted))
			if r1.Err != nil {
				panic(r1.Err)
			}
			response = r1.Value
		} else {

			r2 := <-this.PrivatePostSellMarketPair(this.Extend(request, paramsOmitted))
			if r2.Err != nil {
				panic(r2.Err)
			}
			response = r2.Value
		}
	} else if typeVar == "instant" {
		if capitalizedSide == "Buy" {

			r3 := <-this.PrivatePostBuyInstantPair(this.Extend(request, paramsOmitted))
			if r3.Err != nil {
				panic(r3.Err)
			}
			response = r3.Value
		} else {

			r4 := <-this.PrivatePostSellInstantPair(this.Extend(request, paramsOmitted))
			if r4.Err != nil {
				panic(r4.Err)
			}
			response = r4.Value
		}
	} else {
		request["price"] = this.PriceToPrecision(symbol, price)
		if capitalizedSide == "Buy" {

			r5 := <-this.PrivatePostBuyPair(this.Extend(request, paramsOmitted))
			if r5.Err != nil {
				panic(r5.Err)
			}
			response = r5.Value
		} else {

			r6 := <-this.PrivatePostSellPair(this.Extend(request, paramsOmitted))
			if r6.Err != nil {
				panic(r6.Err)
			}
			response = r6.Value
		}
	}
	var orderResponse any = func() any {
		if response == nil {
			return map[string]any{}
		}
		return response
	}()
	var order map[string]any = OrderToMap(this.ParseOrder(orderResponse, market))
	order["type"] = typeVar

	ch <- AsyncResult[Order]{Value: OrderFromMap(order)}
	return nil
}

